const VideoWin = ({
  title,
  id,
  URLS=null,
  baseDim=null,
  fullscreenable=false,
  videoStyle={},
  fullscreenStyle={},
  time,
  seekSliderRef,
  $timestamp=null,
  // timestamp=null,
  loop=true,
  scrubbable=false,
  paused0=false,
  project_index,
  win_body_style={},
}) => {
  // jotai
  const timestamp = $timestamp != null ? makeAtom($timestamp) : null

  // util
  const videoTypeFromURL = (url) => {
    if (url.includes('.webm'))
      return 'video/webm'
    else if (url.includes('.mp4'))
      return 'video/mp4'
    else
      return 'video/mp4'
  }
  const getVideoURL = (id, ext) => {
    const res = videoURLs.filter(url => url.includes(id) && url.includes(`.${ext}`))
    return res.length > 0 ? res[0] : null
  }
  const exts = ['webm', 'mp4']
  const urls = URLS != null ? URLS
                            : exts.map(ext => getVideoURL(id, ext))
  const srcs = urls.map((url,i) => <source key={i} src={url} type={videoTypeFromURL(url)} />)
  
  // util
  const setSeek = (vidRef) => {
    if (vidRef.current != null && seekSliderRef.current != null)
      seekSliderRef.current.value = vidRef.current.currentTime
  }
  const setTimestamp = (vidRef) => {
    if (timestamp != null) {
      const vid = vidRef.current
      const perc = vid.currentTime/vid.duration
      const framecount = vid.duration*60
      const framenum = Math.floor(framecount*perc)
      timestamp.set(framenum)
      setSeek(vidRef)
    }
  }

  // jotai
  const fullscreenWin = makeAtom($fullscreenWin)
  // const project_loaders = makeAtom($project_loaders)
  // const project_loaders = makeAtom(PROJECT_LOADERS[project_index])

  // state
  const winref = useRef(null)
  const vidRef = useRef(null)
  const paused = makeState(paused0)
  const fullscreend = fullscreenWin?.val == winref
  const tickInterval = useRef(null)
  const video_loaded = makeState(false)

  // tool callbacks
  const onReset = useCallback(() => {
    vidRef.current.currentTime = '0.0'
    setTimestamp(vidRef)
  }, [paused.val])
  const stepFrame = useCallback((n) => {
    paused.set(true)
    if (vidRef.current != null) {
      const t = parseFloat(vidRef.current.currentTime)
      const dt = n * (1/60)
      vidRef.current.currentTime = t + dt
      setTimestamp(vidRef)
    }
  }, [paused.val])

  // FIXME - put in useEffect []
  document.addEventListener('keydown', (ev) => {
    const key = ev.key.toLowerCase()
    if (key=='shift')
      window.SHIFT_KEY_DOWN = true
  })
  document.addEventListener('keyup', (ev) => {
      const key = ev.key.toLowerCase()
      if (key=='shift')
        window.SHIFT_KEY_DOWN = false
  })

  // FIXME
  // wheel override
  const wheelOverride = (e, shift) => {
    e.preventDefault()
    e.stopPropagation()
    const df = window.SHIFT_KEY_DOWN ? 1 : 50
    const frameDelta = e.deltaY < 0 ? -df : df
    // const frameDelta = -e.deltaX
    stepFrame(frameDelta)
  }
  useEffect(() => {
    if (scrubbable) {
      const vid = vidRef.current
      vid.addEventListener('wheel', wheelOverride)
      return () => window.removeEventListener('wheel', wheelOverride)
    }
  }, [])

  const onPause = useCallback(() => {
    const newPaused = !paused.val
    paused.set(newPaused)

    // tick while playing
    if (!newPaused) {
      if (tickInterval.current != null)
        clearInterval(tickInterval.current)

      // update timestamp while playing
      tickInterval.current = setInterval(() => {
        setTimestamp(vidRef)
        // log('vid tick')
      }, 10)
    }
    else {
      // clear tick interval
      if (tickInterval.current != null) {
        clearInterval(tickInterval.current)
        tickInterval.current = null
      }
    }

    // update timestamp when paused
    setTimestamp(vidRef)
  }, [paused.val])
  useEffect(() => {
    if (vidRef.current == null)
      return
    if (paused.val)
      vidRef.current.pause()
    else
      vidRef.current.play()
  }, [paused.val])
  useEffect(() => {
    if (time != null && time.val >= 0) {
      vidRef.current.currentTime = time.val
      setTimestamp(vidRef)
    }
  }, [time.val])

  // init
  useEffect(() => {
    setTimestamp(vidRef)
  }, [])

  // loading
  const onLoad = () => {
    video_loaded.set(true)
  }

  const tools = {
    pause:      toolButton({
                  id: 'pause',
                  title: paused.val ? 'Play' : 'Pause',
                  icon:  paused.val ? faPlay : faPause,
                  click: onPause,
                }),
    rewind:      toolButton({
                  id: 'rewind',
                  title: 'Rewind',
                  icon:  faBackwardFast,
                  click: onReset,
                }),         
    forwardStep:      toolButton({
                        id: 'forwardStep',
                        title: 'Step Forward',
                        icon:  faForwardStep,
                        click: () => stepFrame(1),
                        hold: () => stepFrame(2),
                      }),
    backwardStep:      toolButton({
                        id: 'backwardStep',
                        title: 'Step Backward',
                        icon:  faBackwardStep,
                        click: () => stepFrame(-1),
                        hold: () => stepFrame(-2),
                      }),
                
  }
  const addTools = scrubbable ? [tools.rewind, tools.pause, tools.backwardStep, tools.forwardStep]
                              : [tools.rewind, tools.pause]

  const style = (
    fullscreend ? {
      // marginBottom: '-5px',
      width: '100%',
      overflow: 'hidden',
      // ...videoStyle
    } :
    {
      marginBottom: '-5px',
      overflow: 'hidden',
      ...videoStyle,
    }
  )

  const content = (
    <video
      ref={vidRef}
      style={style}
      loop={loop}
      muted
      autoPlay
      disablePictureInPicture
      disableRemotePlayback
      onClick={onPause}
      onLoadedData={onLoad}

      // FIXME
      onWheel={scrubbable ? wheelOverride : ()=>{}}
    >
      {srcs}
      Sorry, your browser doesn't support videos.
    </video>
  )
  const title1 = $timestamp != null ? 'Frame '+(!isNaN(timestamp.val) ? timestamp.val : 0)
                                    : title
  return (
    <Win
      id={`video_${id}`}
      winref={winref}
      // title={timestamp != null && timestamp?.val != null && !isNaN(timestamp?.val) ? title+' '+timestamp?.val : title}
      // title={`${title} ${timestamp.val}`}
      title={title1}
      addTools={addTools}
      content={content}
      baseDim={baseDim}
      fullscreenable={fullscreenable}
      evaluating={!video_loaded.val}
      winbodystyle={win_body_style}
    />
  )
}
