const evaluate = (evaluator, src, evaluating, error, inputEds, evalEd, outputEds, asyncOutputEds={}, id='DEFAULT', fn=null) => {
  outputEds.concat(Object.values(asyncOutputEds))
    .forEach(ed => evaluating[ed.id].set(true))

  // recv from ww
  evaluator.onmessage = ({data}) => {
    // async output
    if (data?.op == 'async_set') {
      if (data.id in asyncOutputEds) {
        const id = asyncOutputEds[data.id].id
        // log('async_set','alias',data.id,'id',id)
        const val = data.val
        src[id].set(val)
        evaluating[id].set(false)
        error[id].set(data.error)
      }
    }

    // sync output
    else {
      const results = data.results
      results.forEach(res => {
        const id = res.id
        const val = res.val
        src[id].set(val)
        evaluating[id].set(false)
        error[id].set(res.error)
      })
    }
  }
  
  // send to ww
  const inputsMap = {}
  inputEds.forEach(ed => inputsMap[ed.id] = src[ed.id].val)
  const msg = {
    inputs: inputsMap,
    outputs: outputEds.map(ed => ({id: ed.id})),
    src: src[evalEd.id].val,
    fn: fn,
  }
  evaluator.postMessage(msg)
}
const KeyCtrl = ({
  control,
  kDisplay,
  disabled,
  kID=null
}) => {
  // util
  const char2keycode = {
    'a': 65,
    'd': 68,
    's': 83,
    'w': 87,
    ' ': 32,
    'enter': 13,
    'b': 66,
  }

  // empty key
  if (control == null && kDisplay==null && kID==null) {
    return (
      <span className='kbk empty'>
        <code>{'_'}</code>
      </span>
    )
  }

  // state
  const active = makeState(false)

  if (kID == null)
    kID = kDisplay
  const kDisplayUp = kDisplay.toUpperCase()
  const kIDUp = kID.toUpperCase()
  const onMouse = (down, active) => {
    if (disabled)
      return

    active.set(down)
    const keycode = char2keycode[kID]
    log('kID',kID,'keycode',keycode)
    const e = {
      keyCode: keycode,
      type: down ? 'keydown' : 'keyup',
      preventDefault: ()=>{},
    }
    if (window.WOTO_KEY_HANDLER != null)
      window.WOTO_KEY_HANDLER(e)
  }
  return (
    <TooltipWrapper id={control} title={control}>
      <div
        className={`kbk ${active.val ? 'active' : ''} ${disabled ? 'disabled' : ''}`}
        data-keyboard-key={kIDUp}
        onMouseDown={() => onMouse(true, active)}
        onMouseUp={() => onMouse(false, active)}
        onMouseLeave={() => onMouse(false, active)}
      >
        <code style={{
          // marginTop: '-1px',
          // marginBottom: '-1px',
          marginLeft: '2px',
          marginRight: '2px',
          // fontSize: '10px',
          // fontWeight: 'bold',
        }}>
          {kDisplayUp}
        </code>
      </div>
    </TooltipWrapper>
  )
}
const KeyMap = ({
  grid
}) => {
  const rows = grid.map((row, ri) => {
    const tds = row.map((cell, ci) => {
      const props = cell != null ? {
        control: cell[0],
        kDisplay: cell[1],
        disabled: cell.length > 2 ? cell[2] : false,
        kID: cell.length > 3 ? cell[3] : null,
      } : {}
      return (
        <td key={`${ri}_${ci}`}>
          <KeyCtrl {...props} />
        </td>
      )
    })
    return (
      <tr key={ri}>
        {tds}
      </tr>
    )
  })

  return (
    <table className='keymap'>
      <tbody>
        {rows}
      </tbody>
    </table>
  )
}

