const ping = (ip, set, interval) => {
  const HOST = `wss://${ip}`
  log('start ping',HOST)
  const tryopen = () => {
    const ws = new WebSocket(HOST)
    ws.onopen = (msg) => {
      var t0 = 0
      const sendping = () => {
        t0 = Date.now()
        ws.send('ping')
      }
      sendping()
  
      ws.onmessage = (msg) => {
        if (msg.data == 'pong') {
          const rtt = Date.now()-t0
          set(rtt)
          setTimeout(sendping, interval)
        }
      }
    }
    ws.onclose = () => {
      setTimeout(() => tryopen(), 1000)
    }
    ws.onerror = (msg) => {
      ws.close()
      set(-1)
    }
    // ws.close
  }
  tryopen()
}
const playerListConn = (serverId, ip, players) => {
  const HOST = `wss://${ip}`
  log('playerListConn: HOST:',HOST)
  const tryopen = () => {
    // log('tryopen',serverId)
    const ws = new WebSocket(HOST)
    ws.binaryType = 'arraybuffer'
    ws.onopen = (msg) => {
      window[`_${serverId}_ws`] = ws

      function onPlayerListPack(dv) {
        var offset = 1
        var pLength = dv.getUint8(offset)
        offset++

        const playerList = []
        for (var i = 0; i < pLength; i++) {
            // name
            for (var char, name = "";;) {
                char = dv.getUint16(offset);
                offset += 2;

                if (0 == char) break;
                name += String.fromCharCode(char);
            }

            // color
            for (var char, color = "";;) {
                char = dv.getUint16(offset);
                offset += 2;
            
                if (0 == char) break;
                color += String.fromCharCode(char);
            }

            // bot
            var bot = dv.getUint16(offset) == 1;
            offset += 2;

            playerList.push({name, color, bot})
        }

        // set player list
        players.set(playerList)
      }

      ws.onmessage = (message) => {
        var slimMsg = message.data
        var view = new DataView(slimMsg)
        if (view.buffer.byteLength == 0)
          return
        var packetId = view.getUint8(0)
        if (packetId == 7) {
          onPlayerListPack(view)
        }
      }
    }
    ws.onclose = () => {
      players.set(null)
      setTimeout(() => tryopen(), 1000)
    }
    ws.onerror = _ => ws.close()
  }
  tryopen()
}
