const Plist = ({
  edGroups,
}) => {
  const src = {
    // inputs
    $exercise_weights: makeAtom(eds.$exercise_weights.$src),
    $exercises: makeAtom(eds.$exercises.$src),
    $programs_f1: makeAtom(eds.$programs_f1.$src),

    // eval
    app: makeAtom(eds.app.$src),

    // outputs
    $programs_f2: makeAtom(eds.$programs_f2.$src),
    $programs_f2_plist: makeAtom(eds.$programs_f2_plist.$src),
  }
  const evaluating = {
    // outputs
    $programs_f2: makeAtom(eds.$programs_f2.$evaluating),
    $programs_f2_plist: makeAtom(eds.$programs_f2_plist.$evaluating),
  }
  const error = {
    // outputs
    $programs_f2: makeAtom(eds.$programs_f2.$error),
    $programs_f2_plist: makeAtom(eds.$programs_f2_plist.$error),
  }

  const evalID = 'plist'
  useDebouncedEffect(() => {
    // terminate running workers
    if (evalID in WORKER_POOL)
      WORKER_POOL[evalID].forEach(w => w.terminate())

    // FIXME
    // spawn new worker
    const evaluator = new Worker(new URL('Eval.js', import.meta.url))
    // const evaluator = new Worker('./Eval.js', {type: 'module'})
    WORKER_POOL[evalID] = [evaluator]

    evaluate(evaluator,
             src,
             evaluating,
             error,
             [eds.$exercise_weights, eds.$exercises, eds.$programs_f1], eds.app,
             [eds.$programs_f2, eds.$programs_f2_plist], {},
             evalID)
  },
  [src.$exercise_weights.val, src.$exercises.val, src.$programs_f1.val, src.app.val],
  100)

  return (
    <>
      {/* <h2>
        Plist Converter
        {techRow('js')}
      </h2>
      <p>
        Generates exercise workout routine using {EdRef(eds.$exercise_weights)}, {EdRef(eds.$exercises)} & {EdRef(eds.$programs_f1)} as input.<br/>
        Run {EdRef(eds.app)}. Output to {EdRef(eds.$programs_f2)} and {EdRef(eds.$programs_f2_plist)}.
      </p> */}
      <div className='row' style={{
        // justifyContent: 'space-evenly',
        // justifyContent
        alignItems: 'stretch',
      }}>
        <div className='col' style={{
          maxWidth: '300px',
          flexGrow: 1,
          maxHeight: '869px',
          // backgroundColor: 'red',
        }}>
          {edGroups.inputs}
        </div>
        <div className='col' style={{
          // flexGrow: 0,
          // flexBasis: '100px',
          // backgroundColor: 'blue',
          width: '490px',
          maxHeight: '869px',
        }}>
          {edGroups.app}
        </div>
        <div className='col' style={{
          flexGrow: 1,
          // maxWidth: '500px',
          width: '490px',
          maxHeight: '869px',
          // backgroundColor: 'tan',
        }}>
          {edGroups.outputs}
        </div>
      </div>
    </>
  )
}

