var Dot = function(id, color) {
    var self = {};
    self.id = id;
    self.color = 0;
    self.w = 4;
    self.h = 4;

    self.draw = function() {

        var drawX = self.x + chunkColPixels - clientPosX + gameCanvas.width / 2;
        var drawY = self.y + chunkRowPixels - clientPosY + gameCanvas.height / 2;

        // Adjust scale
        if (self.scale == 1) {
            self.w = 5;
            self.h = 5;
        } else if (self.scale == 2) {
            self.w = 6;
            self.h = 6;
        }

        // Check if on screen
        if (drawX + self.w < 0 || drawX - self.w > gameCanvas.width || drawY + self.h < 0 || drawY - self.h > gameCanvas.height) return;

        if (self.id == 2) {
            drawYot(ctx, drawX, drawY);
        } else {
            drawWot(ctx, drawX, drawY, self.color);
        }
    }

    Dot.list[self.id] = self;
    return self;
}
