const initializeSocket = function(ip) {
    // Return if already connected or connecting
    if (enteredOnce)
      return false

    log('initSocket with ip:'+ip)
    const HOST = `wss://${ip}`
    log('initSocket with HOST:'+HOST)
    ws = new WebSocket(HOST)
    window.GAME_WS = ws
    ws.binaryType = 'arraybuffer'
    enteredOnce = true
    //console.log('ws status 2: ' + ws.readyState);

    ws.onopen = function(message) {
      log('ws open','IN_GAME',window.IN_GAME)
        // window.SET_IN_GAME(true)
        window.IN_GAME.set(true)

        //console.log('opened: ' + message + ' ws status 3: ' + ws.readyState + ' CONST ' + ws.CONNECTING);
        // DEBUG DEFAULT NICKNAME
        //nickname = "lod";

        const color = window.PLAYER_COLOR
        ws.send(['0', nickname, color])
    }

    ws.onmessage = function(message) {
        var slimMsg = message.data;

        // Decode binary
        var view = new DataView(slimMsg);
        if (view.buffer.byteLength == 0) return;

        // //
        // Determine type of msg
        //
        var packetId = view.getUint8(0);
        //console.log('packet ' + packetId);
        switch (packetId) {
            case 0:
                onInitPack(view);
                break;

            case 1:
                onUpdatePack(view);
                break;

            case 2:
                //var t0 = performance.now();
                onChunksPack(view);
                //console.log('onChunksPack: ' + (performance.now() - t0));
                break;

            case 3:
                onActorPack(view);
                break;

            case 4:
                onAddRemovePack(view);
                break;

            case 5:
                onTilesPack(view);
                break;

            case 6:
                onLeaderPack(view);
                break;

            // case 7:
            //     log('on player list pack')
            //     onPlayerListPack(view)
            //     break;

            // case 11:
            //     onKeyPack(view);
            //     break;

            case 66:
                onDeath();
                break;

            case 70:
                onKick();
                break;

            default:
                break;
        }

        // //
        // 'On packet' functions
        //
        function onInitPack(dv) {
            var offset = 1;

            // Tiles
            var cyD = dv.getUint8(offset);
            offset++;
            var cxD = dv.getUint8(offset);
            offset++;
            color = dv.getUint8(offset);
            offset++;

            //console.log('byteLength: ' + dv.buffer.byteLength);
            //console.log(cyD + ', ' + cxD);

            relY = (cyD) * chunkRows;
            relX = (cxD) * chunkCols;
            // console.log('received rel ' + relX + ', ' + relY);

            // Decode map
            //var t0 = performance.now();
            /*for (var i = 0; i < regionRows; i++) {
                //var row = [];

                for (var j = 0; j < regionCols; j++) {
                    var num = dv.getUint8(offset);
                    //row.push(num);
                    MAP[(relY + i) * worldCols + relX + j] = num;

                    offset++;
                }

                //MAP.push(row);
            }*/

            // Set chunk data to map
            for (var i = 0; i < 9; i++) {

                var xCoord = dv.getUint8(offset) + 1;
                offset++;
                var yCoord = dv.getUint8(offset) + 1;
                offset++;
                var chunkColor = dv.getUint8(offset);
                offset++;

                for (var yc = 0; yc < chunkRows; yc++) {

                    for (var xc = 0; xc < chunkCols; xc++) {

                        var value = dv.getInt8(offset);
                        offset++;
                        //console.log('value ' + value + ' at ' + xc + ', ' + yc);
                        MAP[(yCoord * chunkRows + yc) * worldCols + xCoord * chunkCols + xc] = value;
                    }
                }

                //console.log('init ' + xCoord + ', ' + yCoord);
                //fillChunk(xCoord*chunkCols, yCoord*chunkRows, chunkColor, 0, 0);
            }

            //console.log(MAP + '');
            //var t1 = performance.now();
            //console.log('exec: ' + (t1 - t0) + ' ms');

            // Set player
            selfId = dv.getUint16(offset);
            offset += 2;
            const selfColor = dv.getUint16(offset);
            offset += 2;
            var clientY = dv.getUint16(offset);
            offset += 2;
            var clientX = dv.getUint16(offset);
            offset += 2;

            // Decode client name
            for (var char, nameD = "";;) {
                char = dv.getUint16(offset);
                offset += 2;

                if (0 == char) break;
                nameD += String.fromCharCode(char);
            }

            // Decode player display color
            for (var char, displayColor = "";;) {
                char = dv.getUint16(offset);
                offset += 2;

                if (0 == char) break;
                displayColor += String.fromCharCode(char);
            }

            // log('new playa')
            // log(Player.list)
            new Player({
                id: selfId,
                color: selfColor,
                name: nameD,
                displayColor: displayColor,
            });
            // log(Player.list)
            //console.log('client: ' + clientX + ', ' + clientY);
            onJoined(clientX, clientY);
        }

        function onActorPack(dv) {

            var offset = 1;

            var pLength = dv.getUint16(offset);
            offset += 2;

            for (var i = 0; i < pLength; i++) {
                var idD = dv.getUint16(offset);
                offset += 2;
                var colorD = dv.getUint16(offset);
                offset += 2;
                var yD = dv.getUint16(offset);
                offset += 2;
                var xD = dv.getUint16(offset);
                offset += 2;

                // Decode player name
                for (var char, nameD = "";;) {
                    char = dv.getUint16(offset);
                    offset += 2;

                    if (0 == char) break;
                    nameD += String.fromCharCode(char);
                }

                // Decode player display color
                for (var char, displayColor = "";;) {
                    char = dv.getUint16(offset);
                    offset += 2;

                    if (0 == char) break;
                    displayColor += String.fromCharCode(char);
                }

                // If we already have this player, don't add
                if (Player.list[idD] != null) continue;

                //console.log('Found player: ' + nameD);
                var player = new Player({
                    id: idD,
                    color: colorD,
                    name: nameD,
                    displayColor: displayColor,
                });
                player.x = xD;
                player.y = yD;
            }

            // Food
            var fLength = dv.getUint16(offset);
            offset += 2;

            for (var i = 0; i < fLength; i++) {
                var idD = dv.getUint16(offset);
                offset += 2;
                var yD = dv.getUint16(offset);
                offset += 2;
                var xD = dv.getUint16(offset);
                offset += 2;

                // If we already have this food, don't add
                if (Food.list[idD] != null) continue;

                var food = new Food(idD, yD, xD);
            }

            // Dots
            var dLength = dv.getUint16(offset);
            offset += 2;

            for (var i = 0; i < dLength; i++) {
                var idD = dv.getUint16(offset);
                offset += 2;
                var colorD = dv.getUint16(offset);
                offset += 2;
                var yD = dv.getUint16(offset);
                offset += 2;
                var xD = dv.getUint16(offset);
                offset += 2;

                // If we already have this dot, don't add
                if (Dot.list[idD] != null) continue;
                //console.log('actor dot ' + i);

                var dot = new Dot(idD, colorD);
                dot.y = yD;
                dot.x = xD;
            }

        }

        function onLeaderPack(dv) {
            var offset = 1;
            var pLength = dv.getUint8(offset);
            offset++;
            //console.log('onleader ' + pLength + ' dv ' + dv.byteLength);

            leaderboard = [];
            for (var i = 0; i < pLength; i++) {
                var id = dv.getUint16(offset);
                offset += 2;
                for (var char, name = "";;) {
                    char = dv.getUint16(offset);
                    offset += 2;
                    //console.log('offset += 2 ' + char);

                    if (0 == char) break;
                    name += String.fromCharCode(char);
                }
                var score = dv.getUint16(offset);
                offset += 2;
                //console.log('new ' + score + ', ' + name);

                leaderboard.push([name, score, id]);
            }

            leaderboardUpdated = true;
        }

        function onPlayerListPack(dv) {
            var offset = 1
            var pLength = dv.getUint8(offset)
            offset++

            const playerList = []
            for (var i = 0; i < pLength; i++) {
                // name
                for (var char, name = "";;) {
                    char = dv.getUint16(offset);
                    offset += 2;

                    if (0 == char) break;
                    name += String.fromCharCode(char);
                }

                // color
                for (var char, color = "";;) {
                    char = dv.getUint16(offset);
                    offset += 2;
                
                    if (0 == char) break;
                    color += String.fromCharCode(char);
                }

                // bot
                var bot = dv.getUint16(offset) == 1;
                offset += 2;

                playerList.push({name, color, bot})
            }

            // set player list
            if (window.PLAYER_LIST != null)
                window.PLAYER_LIST.set(playerList)
        }

        function onAddRemovePack(dv) {
            // Set flag for foreground
            foregroundUpdated = true;

            var offset = 1;

            var pLength = dv.getUint16(offset);
            offset += 2;
            var foodLength = dv.getUint16(offset);
            offset += 2;
            var restLength = dv.getUint16(offset);
            offset += 2;

            for (var i = 0; i < pLength; i++) {
                var op = dv.getUint16(offset);
                offset += 2;
                var id = dv.getUint16(offset);
                offset += 2;

                if (op == 1) {
                    var colorD = dv.getUint16(offset);
                    offset += 2;

                    if (Player.list[id] != null) return;

                    // Add player (if nonexistent)
                    for (var char, name = "";;) {
                        char = dv.getUint16(offset);
                        offset += 2;

                        if (0 == char) break;
                        name += String.fromCharCode(char);
                    }
                    //console.log('Add player: ' + name + ' id: ' + id);
                    new Player({
                        id: id,
                        color: colorD,
                        name: name
                    });
                } else {
                    // Remove player
                    // console.log('removed player ' + id);
                    //console.log(op + ' Remove player: ' + id);
                    if (id != selfId) delete Player.list[id];
                }
            }

            for (var i = 0; i < foodLength; i++) {
                var op = dv.getUint16(offset);
                offset += 2;
                var id = dv.getUint16(offset);
                offset += 2;

                if (op == 1) {
                    if (Food.list[id] != null) return;

                    // Add food
                    var yD = dv.getUint16(offset);
                    offset += 2;
                    var xD = dv.getUint16(offset);
                    offset += 2;

                    var food = new Food(id, yD, xD);

                } else {
                    // Remove food
                    //console.log('Remove food: ' + id);
                    delete Food.list[id];
                }
            }

            for (var i = 0; i < restLength; i++) {
                var op = dv.getUint16(offset);
                offset += 2;
                var id = dv.getUint16(offset);
                offset += 2;

                if (op == 1) {
                    var color = dv.getUint16(offset);
                    offset += 2;

                    if (Dot.list[id] != null) return;

                    // Add dot
                    //console.log('Add dot: ' + id);
                    var dot = new Dot(id, color);
                } else {
                    // Remove dot
                    //console.log('Remove dot: ' + id);
                    delete Dot.list[id];
                }
            }
        }

        function onUpdatePack(dv) {
            //console.log('BUFFER: ' + dv.buffer.byteLength);
            var offset = 1;

            var playerUpdates = dv.getUint16(offset);
            //console.log('playerUpdates: ' + playerUpdates);
            offset += 2;

            // Players
            //console.log('playerUpdates: ' + playerUpdates);
            if (playerUpdates > 0) {
                for (var i = 0; i < playerUpdates; i++) {

                    var idD = dv.getUint16(offset);
                    offset += 2;
                    var colorD = dv.getUint16(offset);
                    offset += 2;
                    var yD = dv.getUint16(offset);
                    offset += 2;
                    var xD = dv.getUint16(offset);
                    offset += 2;

                    // Decode player display color
                    for (var char, displayColor = "";;) {
                        char = dv.getUint16(offset);
                        offset += 2;

                        if (0 == char) break;
                        displayColor += String.fromCharCode(char);
                    }

                    if (Player.list[idD] != null) {
                        var player = idD == selfId ? client : Player.list[idD];

                        if (xD - player.x != 0) player.vx = Math.sign(xD - player.x);
                        player.y = yD;
                        player.x = xD;
                        player.color = colorD;
                        player.displayColor = displayColor

                        // If client, update position
                        if (player.id == client.id) setClientPosition();

                    } else {
                        // console.log('new Player ' + idD + ' ERROR');
                    }
                }

                foregroundUpdated = true;
            }

            var dotUpdates = dv.getUint16(offset);
            offset += 2;

            // Dots
            if (dotUpdates > 0) {
                for (var i = 0; i < dotUpdates; i++) {
                    var idD = dv.getUint16(offset);
                    offset += 2;
                    var colorD = dv.getUint16(offset);
                    offset += 2;
                    var yD = dv.getUint16(offset);
                    offset += 2;
                    var xD = dv.getUint16(offset);
                    offset += 2;

                    //console.log(Dot.list);
                    if (Dot.list[idD] != null) {
                        var dot = Dot.list[idD];

                        dot.y = yD;
                        dot.x = xD;
                        dot.color = colorD;

                    } else {
                        // console.log('ERROR: new dot on update');
                    }
                }

                foregroundUpdated = true;
            }

        }
    }

    ws.onclose = (event) => {
        onDeath(true)
    }
}
