// Canvas cache
///////////////
function createCache() {
    var cacheCanvas = document.createElement('canvas');
    cacheCanvas.className = 'wotocanvas'
    var ctxc = cacheCanvas.getContext('2d');

    // Scale here ONLY
    // Shouldn't perform any scaling on 'resize' or 'drawTile'
    // Use SCALE as logical scaler

    // 'Raw' size
    var w = RAW_TILE * 16 + 10;
    var h = RAW_TILE * 4;
    var RAW_TILE_HALF = RAW_TILE / 2;

    // 'Logical' size, to be used by canvas, not css
    var width = w * SCALE;
    var height = h * SCALE;

    // 'Physical' size, dependant on device                             (also need to consider backingStore)
    var scaledWidth = width * DPR;
    var scaledHeight = height * DPR;

    cacheCanvas.width = scaledWidth;
    cacheCanvas.height = scaledHeight;

    cacheCanvas.style.width = width + 'px';
    cacheCanvas.style.height = height + 'px';

    // No smoothing!
    ctxc.imageSmoothingEnabled = false;
    ctxc.mozImageSmoothingEnabled = false;
    ctxc.webkitImageSmoothingEnabled = false;

    // Scale 'raw' size to 'logical' and then to 'physical'
    ctxc.scale(SCALE * DPR, SCALE * DPR);

    // Debug BG
    //ctxc.fillStyle = 'magenta';
    //ctxc.fillRect(0, 0, cacheCanvas.width, cacheCanvas.height);

    var wotlas = new Image();
    wotlas.onload = function() {
        ctxc.drawImage(wotlas, 128, 0);
    }
    wotlas.src = img_wotlas

    var atlas = new Image();
    atlas.onload = function() {
        // Dirty yet effective
        for (var color = 0; color < 4; color++) {
            for (var i = 0; i < 16; i++) {
                var angle = 0;
                var xSource = 0;

                switch (i) {
                    case 1:
                        xSource = 2;
                        angle = -90;
                        break;
                    case 2:
                        xSource = 2;
                        angle = 180;
                        break;
                    case 3:
                        xSource = 1;
                        angle = 180;
                        break;
                    case 4:
                        xSource = 2;
                        break;
                    case 5:
                        xSource = 1;
                        angle = -90;
                        break;
                    case 6:
                        xSource = 4;
                        break;
                    case 7:
                        xSource = 3;
                        angle = 180;
                        break;
                    case 8:
                        xSource = 2;
                        angle = 90;
                        break;
                    case 9:
                        xSource = 4;
                        angle = 90;
                        break;
                    case 10:
                        xSource = 1;
                        angle = 90;
                        break;
                    case 11:
                        xSource = 3;
                        angle = 90;
                        break;
                    case 12:
                        xSource = 1;
                        break;
                    case 13:
                        xSource = 3;
                        angle = -90;
                        break;
                    case 14:
                        xSource = 3;
                        break;
                    case 15:
                        xSource = 5;
                        break;

                    default:
                        break;
                }

                ctxc.save();
                ctxc.translate(((i * RAW_TILE) + RAW_TILE_HALF), (color * RAW_TILE) + RAW_TILE_HALF);
                ctxc.rotate(angle * Math.PI / 180);
                ctxc.drawImage(
                    atlas,
                    xSource * RAW_TILE, color * RAW_TILE, RAW_TILE, RAW_TILE, // source coords       (raw size)
                    -RAW_TILE_HALF, -RAW_TILE_HALF, RAW_TILE, RAW_TILE // destination coords  (also raw size)
                );
                ctxc.restore();
            }

        }

        // Populate tile cache
        //populateTileCache();

    }
    atlas.src = img_atlas

    // Debug tilemap
    //document.getElementsByTagName('body')[0].appendChild(cacheCanvas);
    //document.getElementById('gameDiv').appendChild(cacheCanvas);

    return cacheCanvas;
}

