function updateTileCache(y, x, id) {
    var ctxtc = tileCache.getContext('2d');
    //ctxtc.fillStyle = x < 175 ? '#cef4bb' : '#d0e5fa';
    //ctxtc.fillStyle = 'red';
    var index = calculateTileIndex(id, y, x, 0, 0);

    // Adjust coordinates for drawing
    x = (x - relX) * TILE;
    y = (y - relY) * TILE;

    // Clear tile space
    ctxtc.clearRect(x, y, TILE, TILE);
    //ctxtc.fillRect(x, y, TILE, TILE);
    if (id == 0) return index;

    // Draw tile
    drawTile(ctxtc, id, index, x, y);

    return index;
}
function populateTileCache() {
    // Bail if map isn't loaded
    //if (MAP.length == 0) return;

    var ctxtc = tileCache.getContext('2d');
    ctxtc.clearRect(0, 0, tileCache.width, tileCache.heigth);
    for (var i = 0; i < regionRows; i++) {
        for (var j = 0; j < regionCols; j++) {

            //var value = MAP[i][j];
            //var value = MAP[relY * worldCols + i * chunkCols + j];
            var value = MAP[(relY + i) * worldCols + relX + j];
            if (value > 0) {
                var tx = j * TILE;
                var ty = i * TILE;

                var index = calculateTileIndex(value, i, j, relY, relX);
                //ctxtc.clearRect(tx, ty, TILE, TILE);
                drawTile(ctxtc, value, index, tx, ty);
            }

        }
    }
}
function translateTileCacheChunk(y, x) {
    var ctxtc = tileCache.getContext('2d');
    var ctxtemp = tempCache.getContext('2d');
    ctxtemp.clearRect(0, 0, tempCache.width, tempCache.height);

    //console.log('tempCache: ' + tempCache.width + ' col: ' + TILE * chunkCols * 3);

    // Down
    if (y == 1 && x == 0) {
        ctxtemp.drawImage(tileCache,
            // Source
            0, chunkColPixels,
            regionColPixels, 2 * chunkRowPixels - TILE,
            // Dest
            0, 0,
            regionColPixels, 2 * chunkRowPixels - TILE
        );

        // Clear entire canvas
        ctxtc.clearRect(0, 0, tileCache.width, tileCache.height);

        // Redraw saved chunks
        ctxtc.drawImage(tempCache,
            0, 0,
            regionColPixels, 2 * chunkRowPixels - TILE,

            0, 0,
            regionColPixels, 2 * chunkRowPixels - TILE
        );
    }
    // Right
    else if (y == 0 && x == 1) {
        ctxtemp.drawImage(tileCache,
            // Source
            chunkColPixels, 0,
            2 * chunkColPixels - TILE, regionRowPixels,
            // Dest
            0, 0,
            2 * chunkColPixels - TILE, regionRowPixels
        );

        // Clear entire canvas
        ctxtc.clearRect(0, 0, tileCache.width, tileCache.height);

        // Redraw saved chunks
        ctxtc.drawImage(tempCache,
            0, 0,
            2 * chunkColPixels - TILE, regionRowPixels,

            0, 0,
            2 * chunkColPixels - TILE, regionRowPixels
        );

    }
    // Left
    else if (y == 0 && x == -1) {
        ctxtemp.drawImage(tileCache,
            // Source
            TILE, 0,
            2 * chunkColPixels - TILE, regionRowPixels,
            // Dest
            0, 0,
            2 * chunkColPixels - TILE, regionRowPixels
        );

        // Clear entire canvas
        ctxtc.clearRect(0, 0, tileCache.width, tileCache.height);

        // Redraw saved chunks
        ctxtc.drawImage(tempCache,
            0, 0,
            2 * chunkColPixels - TILE, regionRowPixels,

            chunkColPixels + TILE, 0,
            2 * chunkColPixels - TILE, regionRowPixels
        );

    }
    // Up
    else if (y == -1 && x == 0) {
        ctxtemp.drawImage(tileCache,
            // Source
            0, TILE,
            regionColPixels, 2 * chunkRowPixels - TILE,
            // Dest
            0, 0,
            regionColPixels, 2 * chunkRowPixels - TILE
        );

        // Clear entire canvas
        ctxtc.clearRect(0, 0, tileCache.width, tileCache.height);

        // Redraw saved chunks
        ctxtc.drawImage(tempCache,
            0, 0,
            regionColPixels, 2 * chunkRowPixels - TILE,

            0, chunkRowPixels + TILE,
            regionColPixels, 2 * chunkRowPixels - TILE
        );
    }
}
function drawTileCacheRow(y, x1, length) {

    var ctxtc = tileCache.getContext('2d');

    // Clear row
    ctxtc.clearRect(x1*TILE - relX*TILE, y2*TILE - relY*TILE, chunkCols*TILE, TILE);
    //ctxtc.fillStyle = 'red';
    //ctxtc.fillRect(x1*TILE - relX*TILE, y2*TILE - relY*TILE, chunkColPixels, TILE);

    for (var j = x1, l = x1 + length; j < l; j++) {

        var value = MAP[y + j];
        //console.log((x1) + ' draw value ' + value);
        var y2 = y / worldCols;
        var tx = j * TILE - relX * TILE;
        var ty = y2 * TILE - relY * TILE;

        //ctxtc.fillRect(tx, ty, TILE, TILE);

        if (value > 0) {
            //console.log('tile at ' + ty + ', ' + tx + ' worldCols ' + worldCols);
            //var t0 = performance.now();
            var index = calculateTileIndex(value, y2, j, 0, 0);
            //console.log('index ' + (performance.now() - t0));
            drawTile(ctxtc, value, index, tx, ty);
        }
    }
}

